<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { ArrowRight, ArrowUpRight, CircleUserRound, Link, Sprout, UserCheck, Users } from 'lucide-vue-next';
import { api, errorMessage } from '../services/api'; import { useAuthStore } from '../stores/auth'; import { useLocale } from '../composables/useLocale'; import { date, initials } from '../utils/format';
import SummaryCard from '../components/ui/SummaryCard.vue'; import AppButton from '../components/ui/AppButton.vue'; import LoadingState from '../components/ui/LoadingState.vue'; import StatusBadge from '../components/ui/StatusBadge.vue';
interface Dashboard { total: number; active: number; linked: number; inactive: number; recent: { id: string; fullName: string; memberNo: string; joinedAt: string; status: string }[]; }
const data = ref<Dashboard>(); const error = ref(''); const busy = ref(false); const auth = useAuthStore(); const { t } = useLocale();
async function load() { busy.value = true; error.value = ''; try { data.value = (await api.get('/dashboard')).data; } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; } }
onMounted(load);
</script>
<template><div class="page-heading"><div><span class="eyebrow">YOUR SOCIETY AT A GLANCE</span><h1>{{ t('Overview') }}<span class="heading-dot">.</span></h1><p>A clear view of your people, all in one place.</p></div><RouterLink v-if="auth.can('members.write')" to="/members/new" class="btn btn-primary"><span>+</span>{{ t('Add member') }}</RouterLink></div><div v-if="error" class="alert error" role="alert">{{ error }} <AppButton variant="ghost" @click="load">Retry</AppButton></div><LoadingState v-if="busy" /><template v-else-if="data"><section class="welcome-banner"><div><span class="welcome-label"><span class="online-dot"></span> YOUR COMMUNITY, CONNECTED</span><h2>Every member matters.</h2><p>Keep profiles up to date and help your community grow.</p><RouterLink to="/members">Explore your member directory <ArrowRight :size="17" /></RouterLink></div><div class="banner-art" aria-hidden="true"><span></span><span></span><Sprout :size="90" :stroke-width="1.2" /></div></section><section class="summary-grid" aria-label="Member summary"><SummaryCard :label="t('Total members')" :value="data.total" detail="Registered in your society"><Users :size="20" /></SummaryCard><SummaryCard :label="t('Active members')" :value="data.active" detail="Currently active memberships"><UserCheck :size="20" /></SummaryCard><SummaryCard :label="t('Portal access')" :value="data.linked" detail="Members with a personal login"><Link :size="20" /></SummaryCard><SummaryCard :label="t('Inactive members')" :value="data.inactive" detail="Inactive or suspended"><CircleUserRound :size="20" /></SummaryCard></section><section class="dashboard-grid"><article class="panel recent-panel"><div class="panel-heading"><div><h2>Recently added members</h2><p>The newest people in your community.</p></div><RouterLink to="/members" class="text-link">View all <ArrowUpRight :size="16" /></RouterLink></div><div v-if="!data.recent.length" class="empty-state"><Users :size="32" /><h3>Your community starts here</h3><p>Add your first member to get things moving.</p><RouterLink v-if="auth.can('members.write')" to="/members/new" class="text-link">Add a member <ArrowRight :size="16" /></RouterLink></div><RouterLink v-for="member in data.recent" :key="member.id" :to="`/members/${member.id}`" class="recent-member"><span class="avatar">{{ initials(member.fullName) }}</span><div><strong>{{ member.fullName }}</strong><small>{{ member.memberNo }}</small></div><span class="recent-date">{{ date(member.joinedAt) }}</span><StatusBadge :status="member.status" /></RouterLink></article><article class="panel getting-started"><span class="eyebrow">A GOOD PLACE TO START</span><h2>Build your member directory</h2><p>Keep the information that matters close at hand.</p><ol><li><span>01</span><div><strong>Add your members</strong><p>Contact details, photos and membership status.</p></div></li><li><span>02</span><div><strong>Record nominee details</strong><p>Keep family and beneficiary information together.</p></div></li><li><span>03</span><div><strong>Give members access</strong><p>A private, view-only space for each member.</p></div></li></ol></article></section><div class="phase-note"><ShieldCheckIcon /><div><strong>A foundation for what comes next</strong><p>Financial records, approvals, reports and offline backups are planned for future phases.</p></div><span class="phase-pill">PHASE 1</span></div></template></template>
<script lang="ts">
import { ShieldCheck as ShieldCheckIcon } from 'lucide-vue-next';
export default { components: { ShieldCheckIcon } };
</script>
